# Start with "DISC".
# Be exactly 8 characters long.
# Not contain any lowercase letters

test = ["DISCTTTT","DISAAAAA","DISCKKKKK","DISCaaaa"]

def is_valid_code(ipt):
  if len(ipt) != 8:
    return False
  if not ipt[0:4] == "DISC":
    return False
  if ipt.upper() == ipt:
    return True
  return False

for i in test:
  print(is_valid_code(i))
